-- 00_PRECHECK.sql — 클라우드 현재 상태 점검 (조회 전용 · 변경 없음) · SCM_MGR 로 접속해 실행
-- [A] EXPECTED_MISSING 이 비어 있지 않은 객체 = 사내 보완분이 빠진 '수정 전 소스' → 해당 1x 파일 적용 대상
-- [A] CLOUD_ONLY_MARKERS 가 있으면 클라우드에만 있는 수정 → 그 객체는 전체교체 금지 (결과 공유 요청)
-- [B] EXCEL_COLUMNS DIFF_* = 사내 값과 차이 → 30 파일 적용
-- [C] 의존 객체 MISSING 행이 있으면 1x 적용 시 컴파일 실패 → 먼저 알려 주세요
SET PAGESIZE 200 LINESIZE 400 LONG 100000
COLUMN OBJECT_NAME FORMAT A30
COLUMN OBJECT_TYPE FORMAT A14
COLUMN EXPECTED_MISSING FORMAT A120
COLUMN CLOUD_ONLY_MARKERS FORMAT A80

-- [A] 객체별 보완 마커
SELECT O.OBJECT_NAME, O.OBJECT_TYPE, O.STATUS, TO_CHAR(O.LAST_DDL_TIME,'YYYY-MM-DD HH24:MI:SS') LAST_DDL,
       (SELECT COUNT(*) FROM USER_SOURCE S WHERE S.NAME=O.OBJECT_NAME AND S.TYPE=O.OBJECT_TYPE) SRC_LINES,
       (SELECT LISTAGG(E.M, ',') WITHIN GROUP (ORDER BY E.M) FROM (SELECT COLUMN_VALUE M FROM TABLE(SYS.ODCIVARCHAR2LIST('-NONE-'))) E
         WHERE E.M <> '-NONE-' AND NOT EXISTS (SELECT 1 FROM USER_SOURCE S WHERE S.NAME=O.OBJECT_NAME AND S.TYPE=O.OBJECT_TYPE AND INSTR(S.TEXT, E.M) > 0)) EXPECTED_MISSING,
       (SELECT LISTAGG(X.M, ',') WITHIN GROUP (ORDER BY X.M) FROM (SELECT DISTINCT REGEXP_SUBSTR(S.TEXT, 'E20[0-9]{6}-[A-Z0-9_]+|hook#[0-9]+') M FROM USER_SOURCE S
          WHERE S.NAME=O.OBJECT_NAME AND S.TYPE=O.OBJECT_TYPE AND REGEXP_LIKE(S.TEXT, 'E20[0-9]{6}-[A-Z0-9_]+|hook#[0-9]+')) X
         WHERE X.M NOT IN ('-NONE-')) CLOUD_ONLY_MARKERS
  FROM USER_OBJECTS O WHERE O.OBJECT_NAME='PKG_NSCM_UI_EXCEL' AND O.OBJECT_TYPE='PACKAGE';

SELECT O.OBJECT_NAME, O.OBJECT_TYPE, O.STATUS, TO_CHAR(O.LAST_DDL_TIME,'YYYY-MM-DD HH24:MI:SS') LAST_DDL,
       (SELECT COUNT(*) FROM USER_SOURCE S WHERE S.NAME=O.OBJECT_NAME AND S.TYPE=O.OBJECT_TYPE) SRC_LINES,
       (SELECT LISTAGG(E.M, ',') WITHIN GROUP (ORDER BY E.M) FROM (SELECT COLUMN_VALUE M FROM TABLE(SYS.ODCIVARCHAR2LIST('E20260914-EXCELROW'))) E
         WHERE E.M <> '-NONE-' AND NOT EXISTS (SELECT 1 FROM USER_SOURCE S WHERE S.NAME=O.OBJECT_NAME AND S.TYPE=O.OBJECT_TYPE AND INSTR(S.TEXT, E.M) > 0)) EXPECTED_MISSING,
       (SELECT LISTAGG(X.M, ',') WITHIN GROUP (ORDER BY X.M) FROM (SELECT DISTINCT REGEXP_SUBSTR(S.TEXT, 'E20[0-9]{6}-[A-Z0-9_]+|hook#[0-9]+') M FROM USER_SOURCE S
          WHERE S.NAME=O.OBJECT_NAME AND S.TYPE=O.OBJECT_TYPE AND REGEXP_LIKE(S.TEXT, 'E20[0-9]{6}-[A-Z0-9_]+|hook#[0-9]+')) X
         WHERE X.M NOT IN ('E20260914-EXCELROW')) CLOUD_ONLY_MARKERS
  FROM USER_OBJECTS O WHERE O.OBJECT_NAME='PKG_NSCM_UI_EXCEL' AND O.OBJECT_TYPE='PACKAGE BODY';

SELECT O.OBJECT_NAME, O.OBJECT_TYPE, O.STATUS, TO_CHAR(O.LAST_DDL_TIME,'YYYY-MM-DD HH24:MI:SS') LAST_DDL,
       (SELECT COUNT(*) FROM USER_SOURCE S WHERE S.NAME=O.OBJECT_NAME AND S.TYPE=O.OBJECT_TYPE) SRC_LINES,
       (SELECT LISTAGG(E.M, ',') WITHIN GROUP (ORDER BY E.M) FROM (SELECT COLUMN_VALUE M FROM TABLE(SYS.ODCIVARCHAR2LIST('-NONE-'))) E
         WHERE E.M <> '-NONE-' AND NOT EXISTS (SELECT 1 FROM USER_SOURCE S WHERE S.NAME=O.OBJECT_NAME AND S.TYPE=O.OBJECT_TYPE AND INSTR(S.TEXT, E.M) > 0)) EXPECTED_MISSING,
       (SELECT LISTAGG(X.M, ',') WITHIN GROUP (ORDER BY X.M) FROM (SELECT DISTINCT REGEXP_SUBSTR(S.TEXT, 'E20[0-9]{6}-[A-Z0-9_]+|hook#[0-9]+') M FROM USER_SOURCE S
          WHERE S.NAME=O.OBJECT_NAME AND S.TYPE=O.OBJECT_TYPE AND REGEXP_LIKE(S.TEXT, 'E20[0-9]{6}-[A-Z0-9_]+|hook#[0-9]+')) X
         WHERE X.M NOT IN ('-NONE-')) CLOUD_ONLY_MARKERS
  FROM USER_OBJECTS O WHERE O.OBJECT_NAME='PKG_DMF0074' AND O.OBJECT_TYPE='PACKAGE';

SELECT O.OBJECT_NAME, O.OBJECT_TYPE, O.STATUS, TO_CHAR(O.LAST_DDL_TIME,'YYYY-MM-DD HH24:MI:SS') LAST_DDL,
       (SELECT COUNT(*) FROM USER_SOURCE S WHERE S.NAME=O.OBJECT_NAME AND S.TYPE=O.OBJECT_TYPE) SRC_LINES,
       (SELECT LISTAGG(E.M, ',') WITHIN GROUP (ORDER BY E.M) FROM (SELECT COLUMN_VALUE M FROM TABLE(SYS.ODCIVARCHAR2LIST('E20260816-NULLFIX','E20260818-GTTDEL','E20260825-DASHRM','E20260825-DATECONV','E20260827-D4','E20260827-D5','hook#150'))) E
         WHERE E.M <> '-NONE-' AND NOT EXISTS (SELECT 1 FROM USER_SOURCE S WHERE S.NAME=O.OBJECT_NAME AND S.TYPE=O.OBJECT_TYPE AND INSTR(S.TEXT, E.M) > 0)) EXPECTED_MISSING,
       (SELECT LISTAGG(X.M, ',') WITHIN GROUP (ORDER BY X.M) FROM (SELECT DISTINCT REGEXP_SUBSTR(S.TEXT, 'E20[0-9]{6}-[A-Z0-9_]+|hook#[0-9]+') M FROM USER_SOURCE S
          WHERE S.NAME=O.OBJECT_NAME AND S.TYPE=O.OBJECT_TYPE AND REGEXP_LIKE(S.TEXT, 'E20[0-9]{6}-[A-Z0-9_]+|hook#[0-9]+')) X
         WHERE X.M NOT IN ('E20260816-NULLFIX','E20260818-GTTDEL','E20260825-DASHRM','E20260825-DATECONV','E20260827-D4','E20260827-D5','hook#150')) CLOUD_ONLY_MARKERS
  FROM USER_OBJECTS O WHERE O.OBJECT_NAME='PKG_DMF0074' AND O.OBJECT_TYPE='PACKAGE BODY';

-- [B] SCM_ADM_EXCEL_COLUMNS — 사내 값과 다르면 DIFF_* = 'DIFF' (행이 안 나오면 = 미존재 → 30 적용)
SELECT PROGRAM_ID, SHEET_NAME,
       CASE WHEN STORAGE_SQL_ID = 'PKG_DMF0074.P_DMF0074_EXCEL_UPLOAD' THEN 'SAME' ELSE 'DIFF' END DIFF_STORAGE_SQL_ID,
       CASE WHEN DBMS_LOB.COMPARE(TO_CLOB(HEADER_CONTENT), TO_CLOB('Div|Plan Date|Team|End Customer|Project Code|Project|Model Code|Metal Link|Sales Site|Currency|FCST type|Exception|Energy|Key_Ni|Key_Co|Key_Li2CO3|Key_LIOH|Key_Al|Key_Mn|Key_Cu|Period(Fr)_Ni|Period(Fr)_Co|Period(Fr)_Li2CO3|Period(Fr)_LIOH|Period(Fr)_Al|Period(Fr)_Mn|Period(Fr)_Cu|Period(To)_Ni|Period(To)_Co|Period(To)_Li2CO3|Period(To)_LIOH|Period(To)_Al|Period(To)_Mn|Period(To)_Cu|Contract Price(/kg)_Ni|Contract Price(/kg)_Co|Contract Price(/kg)_Li2CO3|Contract Price(/kg)_LIOH|Contract Price(/kg)_Al|Contract Price(/kg)_Mn|Contract Price(/kg)_Cu|Change Price(/kg)_Ni|Change Price(/kg)_Co|Change Price(/kg)_Li2CO3|Change Price(/kg)_LIOH|Change Price(/kg)_Al|Change Price(/kg)_Mn|Change Price(/kg)_Cu|Metal Index (kg/Biz type)_Ni|Metal Index (kg/Biz type)_Co|Metal Index (kg/Biz type)_Li2CO3|Metal Index (kg/Biz type)_LIOH|Metal Index (kg/Biz type)_Al|Metal Index (kg/Biz type)_Mn|Metal Index (kg/Biz type)_Cu')) = 0 THEN 'SAME' ELSE 'DIFF' END DIFF_HEADER_CONTENT,
       CASE WHEN INSTR(HEADER_CONTENT, 'Period(Fr)_Ni') > 0 THEN '2단' WHEN INSTR(HEADER_CONTENT, 'PeriodFr_Ni') > 0 THEN '구 1단' ELSE '?' END HEADER_FORM,
       OPTION_ATTRIBUTE_COLUMN_NUMBER, VALID_YN
  FROM SCM_MGR.SCM_ADM_EXCEL_COLUMNS WHERE PROGRAM_ID = 'DMF0074' AND SHEET_NAME = 'Metal Link Price';
SELECT PROGRAM_ID, SHEET_NAME,
       CASE WHEN STORAGE_SQL_ID = 'PKG_DMF0074.P_DMF0074_EXCEL_UPLOAD' THEN 'SAME' ELSE 'DIFF' END DIFF_STORAGE_SQL_ID,
       CASE WHEN DBMS_LOB.COMPARE(TO_CLOB(HEADER_CONTENT), TO_CLOB('Div|Plan Date|Team|End Customer|Model Code|Metal Link|Sales Site|Currency|FCST type|Exception|Energy|Key_Ni|Key_Co|Key_Li2CO3|Key_LIOH|Key_Al|Key_Mn|Key_Cu|Period(Fr)_Ni|Period(Fr)_Co|Period(Fr)_Li2CO3|Period(Fr)_LIOH|Period(Fr)_Al|Period(Fr)_Mn|Period(Fr)_Cu|Period(To)_Ni|Period(To)_Co|Period(To)_Li2CO3|Period(To)_LIOH|Period(To)_Al|Period(To)_Mn|Period(To)_Cu|Contract Price(/kg)_Ni|Contract Price(/kg)_Co|Contract Price(/kg)_Li2CO3|Contract Price(/kg)_LIOH|Contract Price(/kg)_Al|Contract Price(/kg)_Mn|Contract Price(/kg)_Cu|Change Price(/kg)_Ni|Change Price(/kg)_Co|Change Price(/kg)_Li2CO3|Change Price(/kg)_LIOH|Change Price(/kg)_Al|Change Price(/kg)_Mn|Change Price(/kg)_Cu|Metal Index (kg/Biz type)_Ni|Metal Index (kg/Biz type)_Co|Metal Index (kg/Biz type)_Li2CO3|Metal Index (kg/Biz type)_LIOH|Metal Index (kg/Biz type)_Al|Metal Index (kg/Biz type)_Mn|Metal Index (kg/Biz type)_Cu')) = 0 THEN 'SAME' ELSE 'DIFF' END DIFF_HEADER_CONTENT,
       CASE WHEN INSTR(HEADER_CONTENT, 'Period(Fr)_Ni') > 0 THEN '2단' WHEN INSTR(HEADER_CONTENT, 'PeriodFr_Ni') > 0 THEN '구 1단' ELSE '?' END HEADER_FORM,
       OPTION_ATTRIBUTE_COLUMN_NUMBER, VALID_YN
  FROM SCM_MGR.SCM_ADM_EXCEL_COLUMNS WHERE PROGRAM_ID = 'DMF0074_40' AND SHEET_NAME = 'Metal Link Price';
-- [C] 의존 객체 — MISSING 행만 출력 (0행 = 정상). 사내 기준 36개
SELECT D.COLUMN_VALUE REQUIRED, 'MISSING' STATE FROM TABLE(SYS.ODCIVARCHAR2LIST('FN_NEXT_DAY', 'PR_SCM_SYS_LOG_BATCH', 'SCM_MST_ITEM_SN', 'DM_BPS_METAL_LINK_PRICE', 'DM_BPS_METAL_LINK_PRICE_C', 'DM_BPS_METAL_LINK_PRICE_H', 'DM_MST_EXCHANGE_RATE', 'DM_MST_VERSION', 'DM_PLN_SALES_PLAN_C', 'DM_PLN_SALES_PLAN_RESULT_C', 'GT_DM74_TEMP_MST_ITEM', 'GT_DM74_TEMP_MST_ITEM_ENERGY', 'GT_DM74_TEMP_SP_ITEM', 'GT_DM74_TEMP_VERSION_NO', 'GT_DM74_TMP_APPLY_PRICE_TYPE', 'GT_DM74_TMP_CONTRACT_UNIT', 'GT_DM74_TMP_EXCEL_UPLOAD', 'GT_DM74_TMP_EXCEL_UPLOAD_FINAL', 'GT_DM74_TMP_EXCEL_UPLOAD_ITEM', 'GT_DM74_TMP_EXCEL_UPLOAD_RAW', 'GT_DM74_TMP_FROM_PERIOD', 'GT_DM74_TMP_METAL_APPLY', 'GT_DM74_TMP_METAL_LINK_PRICE', 'GT_DM74_TMP_METAL_REQR', 'GT_DM74_TMP_NOTUSE_CODE', 'GT_DM74_TMP_SEARCHED_METAL_LINK_PRICE', 'GT_DM74_TMP_TO_PERIOD', 'SCM_ADM_EXCEL_UPLOAD', 'SCM_ADM_LOOKUP_MASTER_DETAIL', 'SCM_MST_PROJECT', 'SCM_MST_SITE', 'SCM_MST_SITE_ITEM', 'SCM_MST_SSO_DEPT_INFO', 'SCM_SYS_CALENDAR_M', 'DM_MST_ITEM_SINGLE_V', 'SCM_ADM_USER_MNU_EDIT_AUTH_V')) D
 WHERE NOT EXISTS (SELECT 1 FROM USER_OBJECTS O WHERE O.OBJECT_NAME = D.COLUMN_VALUE);
-- [C] PKG_DMF0074 조회부(hook#150)가 쓰는 컬럼 — 0 이면 13 BODY 컴파일 실패
SELECT 'SCM_MST_SITE_ITEM.DEPT_ID' REQUIRED, COUNT(*) EXISTS_CNT FROM USER_TAB_COLUMNS WHERE TABLE_NAME='SCM_MST_SITE_ITEM' AND COLUMN_NAME='DEPT_ID';
-- [C] 검증 기준 데이터 — Key 룩업(사내 Div40 24행) / 앱계정 실행 경로
SELECT SEGMENT1 DIV, COUNT(*) METAL_KEY_VALUE_CNT FROM SCM_ADM_LOOKUP_MASTER_DETAIL WHERE LOOKUP_TYPE='METAL_KEY_VALUE' AND VALID_YN='Y' GROUP BY SEGMENT1 ORDER BY 1;
SELECT OWNER, SYNONYM_NAME, TABLE_OWNER FROM ALL_SYNONYMS WHERE OWNER='SCMP_APP' AND SYNONYM_NAME IN ('PKG_NSCM_UI_EXCEL','PKG_DMF0074');
SELECT GRANTEE, TABLE_NAME, PRIVILEGE FROM USER_TAB_PRIVS WHERE GRANTEE='SCMP_APP' AND TABLE_NAME IN ('PKG_NSCM_UI_EXCEL','PKG_DMF0074');
